#include "catalog/tj_chain.h"
#include <fstream>
#include <iomanip>
#include <iostream>
#include <queue>
#include <map>
#include <random>
using namespace catalog;
struct Records{std::ostream& o;int rows=0,pos=0,zero=0,neg=0;double error=0.,phase=0.;Records(std::ostream& s):o(s){o<<std::setprecision(17)<<"case,sample,modes,weight_real,weight_imag,reference_real,reference_imag,expected,relative_error,beta,path,times\n";}
void add(const std::string& name,int sample,const TJChain& m,const LinkPath& p,DataType ref,int expected){auto z=m.weight(p);double e=std::abs(z-ref)/std::max(1.,std::abs(ref));require(std::isfinite(e)&&e<2e-7,"TJ signed Pf/Fock mismatch");error=std::max(error,e);if(!expected){require(std::abs(z)<1e-10,"TJ expected zero");++zero;}else{require(std::abs(z)>0,"TJ unexpectedly vanished");double d=std::abs(z/std::abs(z)-double(expected));require(d<2e-7,"TJ wrong signed phase");if(expected>0){++pos;phase=std::max(phase,d);}else ++neg;}o<<name<<','<<sample<<','<<m.modes()<<','<<z.real()<<','<<z.imag()<<','<<ref.real()<<','<<ref.imag()<<','<<expected<<','<<e<<','<<p.beta<<',';for(auto s:p.states)o<<s<<':';o<<',';for(auto t:p.times)o<<t<<':';o<<'\n';++rows;}};
void times(LinkPath& p){p.times.clear();for(int k=1;k<int(p.states.size());++k)p.times.push_back(p.beta*k/p.states.size());}
DataType physical(const MatType& h,const LinkPath& p){DataType z=1.;double last=0.;for(int k=0;k<int(p.times.size());++k){z*=-h(p.states[k+1],p.states[k])*std::exp(-(p.times[k]-last)*h(p.states[k],p.states[k]).real());last=p.times[k];}return z*std::exp(-(p.beta-last)*h(p.states.back(),p.states.back()).real());}
std::vector<std::uint64_t> close(const TJChain& m,std::uint64_t from,std::uint64_t to){std::queue<std::uint64_t> q;q.push(from);std::map<std::uint64_t,std::uint64_t> prev;prev[from]=from;while(!q.empty()&&!prev.count(to)){auto s=q.front();q.pop();for(auto t:m.nextStates(s))if(!prev.count(t)){prev[t]=s;q.push(t);}}require(prev.count(to),"TJ closure path missing");std::vector<std::uint64_t> out;for(auto s=to;s!=from;s=prev.at(s))out.push_back(s);std::reverse(out.begin(),out.end());return out;}
int main(int argc,char** argv){try{mkl_set_num_threads(1);mkl_set_dynamic(0);int samples=64;unsigned seed=13106496;std::string csv;for(int i=1;i<argc;++i){std::string key=argv[i];require(i+1<argc,"Missing TJ CLI value");std::string v=argv[++i];if(key=="--samples")samples=std::stoi(v);else if(key=="--seed")seed=std::stoul(v);else if(key=="--csv")csv=v;else throw std::runtime_error("Unknown TJ option");}require(samples>0,"TJ positive samples required");std::ofstream f;if(!csv.empty()){f.open(csv);require(f.good(),"Cannot open TJ CSV");}Records r(csv.empty()?std::cout:f);std::mt19937_64 rng(seed);
 TJChain m;auto h=m.exactHamiltonian();require((h-h.adjoint()).norm()<1e-12,"TJ H not Hermitian");int transitions=0;for(int s=0;s<h.rows();++s){require(std::abs(h(s,s)-m.diagonalEnergy(s))<1e-12,"TJ diagonal wrong");auto next=m.nextStates(s);for(int t=0;t<h.rows();++t)if(t!=s){bool allowed=std::find(next.begin(),next.end(),t)!=next.end();require(allowed==(std::abs(h(t,s))>0),"TJ polynomial H transition mismatch");if(allowed){require((h(t,s)*double(m.squeezedPhase(s)*m.squeezedPhase(t))).real()<0,"TJ squeezed-space gauge failed");LinkPath p;p.states={std::uint64_t(s),std::uint64_t(t),std::uint64_t(s)};times(p);require(std::abs(m.reference(p)-physical(h,p))<1e-12,"TJ independent CAR oracle mismatch");r.add("complete_two_vertex_paths",transitions++,m,p,physical(h,p),1);}}}
 // Conditional hopping keeps each doublon fixed: ordinary quadratic hopping
 // connects this blocked matrix entry, while the written six-fermion term does not.
 require(h(4,1)!=DataType(0.) && h(12,9)==DataType(0.),"TJ conditional hopping not distinguished");
 TJChain bad=m;bad.sites=3;bad.periodic=true;require(!bad.signFreeParameters(),"TJ ring incorrectly admitted");auto hb=bad.exactHamiltonian();LinkPath bp;bp.states={21+1,21+4,21+16,21+1};times(bp);r.add("triangle_spin_exchange_negative",0,bad,bp,physical(hb,bp),-1);
 bp.states={20,17,5,20};times(bp);r.add("triangle_identical_fermion_exchange_negative",0,bad,bp,physical(hb,bp),-1);
 LinkPath blocked;blocked.states={11,14,11};times(blocked);r.add("doublon_blocked",0,m,blocked,0.,0);
 LinkPath zero;zero.states={9,6,9};times(zero);auto mz=m;mz.exchange=0;r.add("zero_exchange",0,mz,zero,0.,0);
 int nonpal=0,mixed=0,blockers=0;for(int n:{4,6}){TJChain model=m;model.sites=n;for(int sample=0;sample<samples;++sample){LinkPath p;p.states={rng()%(std::uint64_t(1)<<model.modes())};bool hasBlock=false;for(int i=0;i<n;++i)hasBlock|=((p.states[0]>>(2*i))&3)==3;blockers+=hasBlock;for(int k=0;k<4+sample%5;++k){auto ns=model.nextStates(p.states.back());if(ns.empty())break;p.states.push_back(ns[rng()%ns.size()]);}auto suffix=close(model,p.states.back(),p.states.front());p.states.insert(p.states.end(),suffix.begin(),suffix.end());times(p);bool hp=false,ex=false;for(int k=0;k<int(p.times.size());++k){if(__builtin_popcountll(p.states[k]^p.states[k+1])==2)hp=true;else ex=true;}mixed+=hp&&ex;nonpal+=!std::equal(p.states.begin(),p.states.end(),p.states.rbegin());auto ref=model.reference(p);if(n==4)require(std::abs(ref-physical(h,p))<1e-12,"TJ random physical oracle mismatch");r.add("random_squeezed_chain",sample,model,p,ref,1);}}
 require(blockers>0,"TJ ensemble lost full-Fock doublons");if(samples>=64)require(nonpal>0&&mixed>0,"TJ random ensemble failed to cover mixed nonretraced paths");
 std::cerr<<"PASS tj_chain rows="<<r.rows<<" positive="<<r.pos<<" zero="<<r.zero<<" negative="<<r.neg<<" max_relative_error="<<r.error<<" max_phase_error="<<r.phase<<" nonpal="<<nonpal<<" mixed="<<mixed<<" seed="<<seed<<'\n';
 }catch(const std::exception& e){std::cerr<<"FAIL tj_chain: "<<e.what()<<'\n';return 1;}return 0;}
